# Portable read-only BHTest viewer. Generated by Build-Viewer.ps1; no modules required.
[CmdletBinding(DefaultParameterSetName='Desktop')]
param([string]$IndexPath,
    [Parameter(ParameterSetName='Browser',Mandatory)][switch]$Browser,
    [Parameter(ParameterSetName='Browser')][switch]$NoBrowser,
    [Parameter(ParameterSetName='Browser')][switch]$NoWindow)
$ErrorActionPreference='Stop'
if ([Environment]::OSVersion.Platform -ne 'Win32NT') { throw 'The viewer requires Windows and its built-in winsqlite3.dll.' }
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
if (-not $IndexPath) {
    Add-Type -AssemblyName System.Windows.Forms
    $picker=New-Object System.Windows.Forms.OpenFileDialog
    $picker.Title='Open a BHTest graph index'; $picker.Filter='BHTest graph index (*.sqlite)|*.sqlite'
    try { if ($picker.ShowDialog() -ne 'OK') { return }; $IndexPath=$picker.FileName } finally { $picker.Dispose() }
}
$IndexPath=(Resolve-Path -LiteralPath $IndexPath).ProviderPath
if (-not ('BH.Native.DesktopViewer' -as [type])) {
    if ('BH.Native.GraphIndex' -as [type]) { throw 'A different BHTest native assembly is already loaded. Start this viewer in a fresh PowerShell session.' }
    $native=@'
/*__NATIVE__*/
'@
    if ($PSVersionTable.PSEdition -eq 'Core') {
        $references=@(Get-ChildItem -LiteralPath (Join-Path $PSHOME 'ref') -Filter '*.dll' | ForEach-Object FullName)
        $references+=@([Windows.Forms.Form].Assembly.Location,[Drawing.Graphics].Assembly.Location)
        $references+=@(Get-ChildItem -LiteralPath $PSHOME -Filter '*Windows*.dll' | Where-Object { $_.Name -match '^System\.(Windows\.Forms\.|Private\.Windows\.)' } | ForEach-Object FullName)
    } else { $references=@('System.dll','System.Core.dll','System.Windows.Forms.dll','System.Drawing.dll') }
    Add-Type -TypeDefinition $native -ReferencedAssemblies $references
}
if (-not $Browser) {
    [BH.Native.DesktopViewer]::Run($IndexPath)
    return
}
$encoded='/*__HTML__*/'
$memory=New-Object IO.MemoryStream(,[Convert]::FromBase64String($encoded))
$gzip=New-Object IO.Compression.GZipStream($memory,[IO.Compression.CompressionMode]::Decompress)
$reader=New-Object IO.StreamReader($gzip,[Text.Encoding]::UTF8)
try { $page=$reader.ReadToEnd() } finally { $reader.Dispose(); $gzip.Dispose(); $memory.Dispose() }
$server=New-Object BH.Native.ViewerServer($IndexPath,$page)
try {
    Write-Host "Read-only index: $IndexPath"
    Write-Host "Viewer: $($server.Url)"
    Write-Host 'Keep this launcher running. Use Stop viewer in the browser, close the launcher window, or press Ctrl+C here to stop.'
    if (-not $NoBrowser) { Start-Process $server.Url }
    if ($NoWindow) {
        while ($server.IsRunning) { Start-Sleep -Milliseconds 200 }
    } else {
        Add-Type -AssemblyName System.Windows.Forms
        Add-Type -AssemblyName System.Drawing
        $window=New-Object Windows.Forms.Form
        $window.Text='BHTest — Local viewer'; $window.Size=New-Object Drawing.Size(600,240)
        $window.StartPosition='CenterScreen'; $window.BackColor=[Drawing.Color]::FromArgb(19,30,48)
        $window.ForeColor=[Drawing.Color]::White; $window.Font=New-Object Drawing.Font('Segoe UI',10)
        $label=New-Object Windows.Forms.Label; $label.SetBounds(22,20,535,90)
        $label.Text="Read-only viewer is running on this computer.`r`n`r`n$IndexPath"; $label.AutoEllipsis=$true
        $open=New-Object Windows.Forms.Button; $open.SetBounds(22,125,170,38); $open.Text='Open viewer'; $open.Add_Click({Start-Process $server.Url})
        $stop=New-Object Windows.Forms.Button; $stop.SetBounds(205,125,170,38); $stop.Text='Stop viewer'; $stop.Add_Click({$window.Close()})
        $window.Controls.AddRange(@($label,$open,$stop))
        $timer=New-Object Windows.Forms.Timer; $timer.Interval=300; $timer.Add_Tick({if(-not $server.IsRunning){$window.Close()}})
        $timer.Start()
        try { [void]$window.ShowDialog() } finally { $timer.Stop(); $timer.Dispose(); $window.Dispose() }
    }
} finally { $server.Dispose() }
